window.VO = [{"id":"n02","text":"Watch the money.","at":0.2,"t0":0.1,"t1":1.095},{"id":"u01","text":"Five hundred? For a ten-rupee chai?","at":2.55,"t0":1.275,"t1":3.715},{"id":"u02","text":"Two hundred.","at":8.83,"t0":4.415,"t1":5.405},{"id":"u03","text":"Four hundred.","at":10.81,"t0":5.405,"t1":6.465},{"id":"u04","text":"Four-fifty.","at":12.93,"t0":6.465,"t1":7.43},{"id":"u05","text":"Four-sev—","at":14.86,"t0":7.43,"t1":8.39},{"id":"u06","text":"Oh, you have change? Then take your five hundred back.","at":17.48,"t0":8.74,"t1":12.005},{"id":"u07","text":"Arre, sorry, sorry!","at":27.41,"t0":13.705,"t1":15.025},{"id":"u08","text":"Four-seventy.","at":30.15,"t0":15.075,"t1":16.14},{"id":"u09","text":"Four-ninety.","at":32.28,"t0":16.14,"t1":17.055},{"id":"u10","text":"Come again!","at":35.61,"t0":17.805,"t1":18.715},{"id":"n04","text":"How much did he steal?","at":38.33,"t0":19.165,"t1":20.53},{"id":"n05","text":"Nothing was hidden.","at":42.66,"t0":21.33,"t1":22.455},{"id":"n06","text":"His five hundred came down, and the uncle counted out four-fifty.","at":45.51,"t0":22.755,"t1":26.53},{"id":"n07","text":"Then a ten for the chai, and his five hundred went back.","at":53.76,"t0":26.88,"t1":29.85},{"id":"n08","text":"But one raised eyebrow, and the uncle counted on: four-seventy, four-ninety.","at":60.7,"t0":30.35,"t1":34.51},{"id":"n09","text":"Four hundred and ninety.","at":69.92,"t0":34.96,"t1":36.41},{"id":"n10","text":"He never picked a pocket.","at":74.12,"t0":37.06,"t1":38.595},{"id":"n11","text":"The uncle counted it all out for him.","at":77.59,"t0":38.795,"t1":40.78},{"id":"n12","text":"Your brain can only hold about four things at once, so he kept handing the uncle one more.","at":82.46,"t0":41.23,"t1":46.075},{"id":"n13","text":"That's why police tell shopkeepers: one deal at a time.","at":92.95,"t0":46.475,"t1":49.625},{"id":"c01","text":"Five hundred?","at":101.45,"t0":50.725,"t1":51.87}];
